head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf05005";
scwin.SCREN_PROCS_TP_CD_07 = "07";  // 엑셀저장 — as-is 공용 상수(공급사 pcc 번들, 화면 안 선언)
scwin.panel_mkt_gubun = null;
scwin.grd_List = null;
scwin.panel_page = null;
scwin.clickBzProcsNo = "";
scwin.dts_List = null;
scwin.fn_list_sync = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.panel_mkt_gubun = $c.util.getComponent('panel_mkt_gubun');
        scwin.grd_List = $c.util.getComponent('grd_List');
        scwin.panel_page = $c.util.getComponent('panel_page');
        scwin.dts_List = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_List')) : $c.util.getComponent('dts_List');
        scwin.fn_list_sync = scwin.tx_script_dts_List;
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf05005.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.Combo_CBDataSetPeriod, $c.fil.showObj
    try {
        fn_initSearchDate(cal_edt_SDate, cal_edt_EDate);
        $c.fil.Combo_CBDataSetPeriod(slc_cmb_PeriodTp);
        if ($c.session.getUserInfo("market") === "1" || $c.session.getUserInfo("market") === "2" || $c.session.getUserInfo("market") === "6") {
            /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("TR_MKT_NM", "Show") */
            /* TODO Stage2: [sdd] 미포팅 대입 — 아래 주석의 대상 */ /* 미포팅 대입 대상: grd_List.getColumnInfo("FSS_UNQ_NO_DUP_YN", "Show") */
            rd_rdo_SPOT_ISU_TRD_MKT_TP_CD.setValue($c.session.getUserInfo("market"));
            scwin.panel_mkt_gubun.hide();
        } else {
            scwin.panel_mkt_gubun.show("");
        }
        if ($c.session.getUserInfo("market") === "6") {
            const usrCBData = "'ST^주권";
            if(slc_cmb_NEW_SECUGRP_ID)slc_cmb_NEW_SECUGRP_ID.CBData=usrCBData;
        }
        scwin.fn_list_sync();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.compareFromToDate2
    try {
        if ($c.fil.compareFromToDate2(cal_edt_SDate, cal_edt_EDate)) {
            scwin.fn_list_sync();
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.btn_Search_onclick' }); }
};

/**
 * @method
 * @name dts_List_onloaderror
 * @description dts_List onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_List);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf05005.dts_List_onloaderror" });
    }
};

/**
 * @method
 * @name dts_List_onloadcompleted
 * @description dts_List onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_onloadcompleted = function (rowcount) {
    try {
        // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.FillGridHeaderTotalCnt
        $c.fil.FillGridHeaderTotalCnt(rowcount, scwin.panel_page);
        void 0;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf05005.dts_List_onloadcompleted" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function () {
    try {
        await scwin.excelDown();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf05005.btn_Excel_onclick' }); }
};

/**
 * @method
 * @name grd_List_ondblclick
 * @description grd_List 더블클릭 이벤트
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_List_ondblclick = function (row, colid) {
    try {
        scwin.openDetail(row);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.grd_List_ondblclick' }); }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function () {
    try {
        if (slc_cmb_NEW_SECUGRP_ID.getValue() === "") {
            await $c.win.alert("신규등록할 [유가증권]을 선택하세요.");
            $c.util.getComponent("slc_cmb_NEW_SECUGRP_ID").focus();
            return;
        } else {
            scwin.openDetail(-999);
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf05005.btn_New_onclick' }); }
};

/**
 * @method
 * @name img_CoSearch_onclick
 * @description img_CoSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CoSearch_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.lc.fn_PopFindExamCorp
    try {
        $c.lc.fn_PopFindExamCorp(rd_rdo_SECUGRP_ID.getValue());

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.img_CoSearch_onclick' }); }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function () {
    try {
        if (ipt_txb_ISUR_CD.value === "") {
            $c.util.getComponent("ipt_txb_COM_NM").setValue("");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.txb_ISUR_CD_onblur' }); }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function () {
    try {
        const vTp = slc_cmb_PeriodTp.valueOfIndex("VALUE", slc_cmb_PeriodTp.Index);
        $c.fil.setFromToDate(vTp, cal_edt_SDate, cal_edt_EDate);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.cmb_PeriodTp_onselchange' }); }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description btn_Close 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame
    try {
        $c.win.closePopup();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf05005.btn_Close_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_script_dts_List
 * @description script dts List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_script_dts_List = async function () {
    $c.util.getComponent("dma_scriptDts_ListReq").set("SCREN_ID", "ULDSTF05005.gfm");
    $c.util.getComponent("dma_scriptDts_ListReq").set("inputMessageId", "NEWLISTING_SEARCH_OUT");
    // as-is 가 URL 에 싣던 값을 정적으로 못 읽었다 — 빈 파라미터로 보내지 않는다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, DIV_IDX, SECUGRP_ID, ISUR_CD, S_DATE, E_DATE, SPOT_ISU_TRD_MKT_TP_CD"
    throw { bizMessage: "보낼 입력값을 아직 읽지 못합니다(전환 미완) — SCREN_PROCES_TP_CD, DIV_IDX, SECUGRP_ID, ISUR_CD, S_DATE, E_DATE, SPOT_ISU_TRD_MKT_TP_CD", unresolved: "query_param:SCREN_PROCES_TP_CD,DIV_IDX,SECUGRP_ID,ISUR_CD,S_DATE,E_DATE,SPOT_ISU_TRD_MKT_TP_CD" };
    const sbmOptions = {
        id: "tx_script_dts_List",
        method: "post",
        action: "/Newlisting.do",
        ref: "dma_scriptDts_ListReq",
        target: "dts_List=body.content",
        isProcessMsg: false,
        submitErrorHandler: (typeof scwin['dts_List_onloaderror'] === 'function') ? scwin['dts_List_onloaderror'] : (typeof scwin['dts_List_onfail'] === 'function') ? scwin['dts_List_onfail'] : undefined
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['dts_List_onloadcompleted'] === 'function') ? scwin['dts_List_onloadcompleted'] : ((typeof scwin['dts_List_onsuccess'] === 'function') ? scwin['dts_List_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('dts_List'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf05005.tx_script_dts_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getPar
 * @description get Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function (arrPar) {
    arrPar[0] = ipt_txb_ISUR_CD.getValue();
    arrPar[1] = ipt_txb_COM_NM.getValue();
    arrPar[2] = rd_rdo_SECUGRP_ID.getValue();
    arrPar[3] = rd_rdo_SPOT_ISU_TRD_MKT_TP_CD.getValue();
    arrPar[4] = SEARCH_TYP_SLR;
    return arrPar , length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function (arrPar) {
    $c.util.getComponent("ipt_txb_ISUR_CD").setValue(arrPar[0].ISUR_CD);
    $c.util.getComponent("ipt_txb_COM_NM").setValue(arrPar[0].COM_NM);
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function (obj) {
    scwin.clickBzProcsNo = scwin.dts_List.getCellData((obj), "BZ_PROCS_NO");
};

/**
 * @method
 * @name getBzProcsNo
 * @description get Bz Procs No 처리
 * @returns {void}
 * @hidden N
 */
scwin.getBzProcsNo = function () {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.doLogSave
    if (scwin.dts_List.getRowCount() > 0) {
        $c.fil.doLogSave("ULDSTF05005.gfm", scwin.SCREN_PROCS_TP_CD_07);
        scwin.grd_List.GridToOffice("신규상장", "", 8, 0);
    } else {
        await $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};

/**
 * @method
 * @name openDetail
 * @description open Detail 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.openDetail = function (row) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CreateDialogFrame, $c.lc.fn_getSecuGrpNm
    let hight;
    let secugrpId;
    let pageNM;
    if (row > 0) {
        scwin.setBzProcsNo(row);
        secugrpId = scwin.dts_List.getCellData(row, 'SECUGRP_ID');
    } else {
        scwin.clickBzProcsNo = "";
        secugrpId = slc_cmb_NEW_SECUGRP_ID.getValue();
    }
    if (secugrpId === SECUGRP_ID_ST) {
        hight = "900";
        pageNM = "ULDSTF05006";
    } else {
        if (secugrpId === SECUGRP_ID_DR || secugrpId === SECUGRP_ID_FS) {
            hight = "900";
            pageNM = "ULDSTF05007";
        }
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.frame.CreateDialogFrame("STOCK_LISTING", (function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("/lstproc/" + pageNM + ".gfm"), $c.lc.fn_getSecuGrpNm(secugrpId) + " 신규상장관리", 220, 0, 1020, hight, "window");
};
// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
